commits.content:
.items-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.item-card {
  position: relative;
  padding: 12px;
  border-radius: 10px;
  background: #f9fafb;
  border: 1px solid #eee;
}

.item-header {
  display: flex;
  justify-content: space-between;
  font-weight: bold;
}

.status {
  font-size: 12px;
  color: #6366f1;
}

.delete-btn {
  position: absolute;
  bottom: 8px;
  left: 8px;
  background: transparent;
  border: none;
  cursor: pointer;
  opacity: 0.6;
}

.delete-btn:hover {
  opacity: 1;
}
